INSERT INTO machine (id, code, name, manufacturer, year, cpu, notes) VALUES (2, 'FX700P', 'Casio FX-700P', 'Casio', NULL, 'Hitachi HD61913A01 (4-bit, internal ROM) (source [4])', 'Programmable calculator: 12-position 5x7 dot matrix LCD, 1568 program steps with 26 memories (up to 222), 10 program areas P0-P9. Two HD61914A RAM chips at $0000-$07FF and $0800-$0FFF (source [4]). Options: FA-3 cassette interface, mini printer.');
INSERT INTO machine (id, code, name, manufacturer, year, cpu, notes) VALUES (100002, 'PB100', 'Casio PB-100', 'Casio', 1982, 'Hitachi HD61913A01, as in the FX-700P (service manual, checked by the editor)', 'The FX-700P with less memory: 544 steps, 26 memories expandable to 94; with the OR-1 RAM pack as much as the FX-700P (222 memories; the scan of the manual reads 1,668 steps). Keys with one or two operations (SHIFT); the functions have no F key and are typed letter by letter.');
INSERT INTO machine (id, code, name, manufacturer, year, cpu, notes) VALUES (100003, 'TRS80_PC4', 'Tandy Radio Shack TRS-80 PC-4', 'Tandy Radio Shack', 1983, 'Hitachi HD61913A01, as in the FX-700P (service manual, checked by the editor)', 'The Casio PB-100 sold under the Radio Shack name.');
INSERT INTO dialect (id, code, name, version, author, year, notes) VALUES (2, 'CASIO_FX700P', 'Casio FX-700P BASIC', NULL, 'Casio', NULL, 'BASIC of a programmable calculator: numeric variables A-Z, character variables A$-Z$ of up to 7 characters and the exclusive character variable $ of up to 30. The same BASIC runs on the Casio PB-100 (less memory, no F key for the functions) and on its rebrandings TRS-80 PC-4 and Olympia OP-544. Memory addresses in the tables are those of the FX-700P.');
INSERT INTO layer (id, code, name, kind, author, year) VALUES (2, 'FX700P_core', 'Casio FX-700P BASIC', 'CORE', 'Casio', NULL);
INSERT INTO dialect_layer (dialect_id, layer_id, position) VALUES (2, 2, 1);
