INSERT INTO character_code (layer_id, code, evidence, notes, kind, name, action) VALUES (2, 254, 'MANUAL', 'The colon of a multistatement; the printable colon is $5F.', 'CONTROL', 'Statement separator', 'Separates two statements on a line');
INSERT INTO character_code (layer_id, code, evidence, notes, kind, name, action) VALUES (2, 255, 'MANUAL', NULL, 'CONTROL', 'End of line', 'Ends a program line');
INSERT INTO memory_area (layer_id, area, prologue, epilogue, notes, evidence) VALUES (2, 'PROGRAM', '', '$E0 after each program area (assumed from the SAVE A files)', 'The programs P0-P9 occupy $0220-$0E5F (3136 nibbles = 1568 steps). Memories expanded with DEFM take their room from the end of this area, 8 steps each.', 'INFERRED');
INSERT INTO memory_area (layer_id, area, prologue, epilogue, notes, evidence) VALUES (2, 'VARIABLES', '', '', 'The memories occupy the end of the RAM, 16 nibbles each, going down: A at $0FF0, B at $0FE0, ..., Z at $0E60, then the expanded memories. The exclusive $ is apart, at $01E0-$021F.', 'INFERRED');
INSERT INTO program_layout_field (layer_id, position, name, offset, size, byte_order, description, evidence) VALUES (2, 1, 'Line number', 0, 2, 'LITTLE', 'Binary-coded decimal, lower two digits first: line 1234 is the bytes `$34 $12`, i.e. the nibbles 4 3 2 1 in memory.', 'MANUAL');
INSERT INTO program_layout_field (layer_id, position, name, offset, size, byte_order, description, evidence) VALUES (2, 2, 'Line text', 2, NULL, NULL, 'Tokens ($80-$C6) and character codes ($00-$7F). Numbers are written as characters (digits $10-$19, point $1A, exponent $1F or $1E for a negative one); the colon between two statements is $FE (inside quotes the colon is the character $5F). Spaces outside quotes are not stored.', 'MANUAL');
INSERT INTO program_layout_field (layer_id, position, name, offset, size, byte_order, description, evidence) VALUES (2, 3, 'End of line', NULL, 1, NULL, '$FF, written when EXE stores the line.', 'MANUAL');
INSERT INTO table_status (table_kind_id, layer_id, status, notes) SELECT id, 2, 'PARTIAL', 'From bas2fx70 [5] and the image of the glyphs [6]: the code of a character is the position of its glyph. $00-$7F characters, $80-$C6 tokens, $FE and $FF control codes. Codes with a blank glyph, and the @ and \ of bas2fx70, to be checked.' FROM table_kind WHERE code = 'CHARACTER_CODES';
INSERT INTO table_status (table_kind_id, layer_id, status, notes) SELECT id, 2, 'TO_DO', 'KEY gives the character of the key pressed; whether keys have codes is not known.' FROM table_kind WHERE code = 'KEYBOARD_CODES';
INSERT INTO table_status (table_kind_id, layer_id, status, notes) SELECT id, 2, 'COMPLETE', 'Shown as `ERRn Pa-l`: n = error code, a = program area, l = line number (in manual calculation only `ERRn`). There is no error 8.' FROM table_kind WHERE code = 'ERRORS';
INSERT INTO table_status (table_kind_id, layer_id, status, notes) SELECT id, 2, 'PARTIAL', 'From p. 10: functions, power, multiplication and division, addition and subtraction; left to right at the same level (the manual''s example `2+3*SIN(17+13)↑2` = 2.75 puts the function before the power). The change of sign is placed before the power as in the PokecomGO2 simulator (source [9]: `-2↑2` = 4); not tested on the real machine.' FROM table_kind WHERE code = 'OPERATOR_PRECEDENCE';
INSERT INTO table_status (table_kind_id, layer_id, status, notes) SELECT id, 2, 'COMPLETE', 'From source [7]. The RAM has 4-bit words, so the fields are given in nibbles. Each memory takes 16 nibbles (8 steps). Memory map of the FX-700P: $0000-$00FF buffers, $0100 ANS, $0110 seed of RAN#, $0120 position for MID, $0140-$01BF FOR stack (4 entries), $01C0-$01DF GOSUB stack (8 entries), $01E0-$021F $, $0220-$0E5F programs, $0E60-$0FFF memories Z to A.' FROM table_kind WHERE code = 'VARIABLE_LAYOUT';
INSERT INTO table_status (table_kind_id, layer_id, status, notes) SELECT id, 2, 'COMPLETE', 'From source [7], confirmed by bas2fx70 [5] and by the step counts of p. 22. The end of each program area ($E0) is assumed.' FROM table_kind WHERE code = 'PROGRAM_LAYOUT';
INSERT INTO table_status (table_kind_id, layer_id, status, notes) SELECT id, 2, 'NOT_APPLICABLE', 'The command list has no sound command.' FROM table_kind WHERE code = 'MUSICAL_NOTES';
INSERT INTO table_status (table_kind_id, machine_id, status, notes) SELECT id, 2, 'COMPLETE', '128 glyphs of 5x7 dots for the codes 0-127, from the image [6]; 14 of them are blank.' FROM table_kind WHERE code = 'GLYPHS';
INSERT INTO table_status (table_kind_id, machine_id, status, notes) SELECT id, 2, 'PARTIAL', 'Assumed: the display shows for each code 0-127 the glyph with the same number.' FROM table_kind WHERE code = 'SCREEN_CODES';
INSERT INTO table_status (table_kind_id, machine_id, status, notes) SELECT id, 2, 'NOT_APPLICABLE', 'Monochrome LCD.' FROM table_kind WHERE code = 'COLORS';
INSERT INTO table_status (table_kind_id, machine_id, status, notes) SELECT id, 100002, 'COMPLETE', '128 glyphs of 5x7 dots for the codes 0-127, from the image [6]; 14 of them are blank.' FROM table_kind WHERE code = 'GLYPHS';
INSERT INTO table_status (table_kind_id, machine_id, status, notes) SELECT id, 100002, 'PARTIAL', 'Assumed: the display shows for each code 0-127 the glyph with the same number.' FROM table_kind WHERE code = 'SCREEN_CODES';
INSERT INTO table_status (table_kind_id, machine_id, status, notes) SELECT id, 100002, 'NOT_APPLICABLE', 'Monochrome LCD.' FROM table_kind WHERE code = 'COLORS';
INSERT INTO table_status (table_kind_id, machine_id, status, notes) SELECT id, 100003, 'COMPLETE', '128 glyphs of 5x7 dots for the codes 0-127, from the image [6]; 14 of them are blank.' FROM table_kind WHERE code = 'GLYPHS';
INSERT INTO table_status (table_kind_id, machine_id, status, notes) SELECT id, 100003, 'PARTIAL', 'Assumed: the display shows for each code 0-127 the glyph with the same number.' FROM table_kind WHERE code = 'SCREEN_CODES';
INSERT INTO table_status (table_kind_id, machine_id, status, notes) SELECT id, 100003, 'NOT_APPLICABLE', 'Monochrome LCD.' FROM table_kind WHERE code = 'COLORS';
INSERT INTO source (id, title, author, publisher, year, kind, url, notes) VALUES (100001, 'FX-700P Instruction Manual', NULL, 'Casio', NULL, 'MANUAL', NULL, 'Scanned English manual, 72 pages; the pages cited are the printed ones.');
INSERT INTO source (id, title, author, publisher, year, kind, url, notes) VALUES (100002, 'FX-730P Owner''s Manual, 4-8 Using a PB-100 Program', NULL, 'Casio', NULL, 'MANUAL', 'https://www.manualslib.com/manual/1058309/Casio-Fx-730p.html?page=93', 'Differences between the PB-100/FX-700P BASIC and the FX-730P one.');
INSERT INTO source (id, title, author, publisher, year, kind, url, notes) VALUES (100003, 'Casio utilities', 'Marcus von Cube', NULL, NULL, 'WEB', 'https://mvcsys.de/doc/casioutil.html', 'The FX-700P does not understand REM; the internal encoding is not ASCII.');
INSERT INTO source (id, title, author, publisher, year, kind, url, notes) VALUES (100004, 'Casio FX-700P - hardware', 'Piotr Piatek', NULL, NULL, 'WEB', 'https://calculators.pdp-11.ru/hardware.htm', 'Microprocessor and RAM chips.');
INSERT INTO source (id, title, author, publisher, year, kind, url, notes) VALUES (100005, 'bas2fx70.c', 'Piotr Piatek', NULL, NULL, 'WEB', 'https://mk.bs0dd.net/piotr433/programs.htm', 'C source of a converter from ASCII BASIC to the FX-700P tape image: keyword tokens, table from ASCII to the Casio character codes, format of a program line and of the tape file.');
INSERT INTO source (id, title, author, publisher, year, kind, url, notes) VALUES (100006, 'FX-700P character set (image)', NULL, NULL, NULL, 'WEB', NULL, 'The 128 glyphs, 5x7 pixels, in a 16x8 grid for the codes 0-127 (data/sources/fx700p_charset.png).');
INSERT INTO source (id, title, author, publisher, year, kind, url, notes) VALUES (100007, 'Casio FX-700P - data formats', 'Piotr Piatek', NULL, NULL, 'WEB', 'https://mk.bs0dd.net/piotr433/formats.htm', 'Memory map, numeric and string variables, program lines, FOR and GOSUB stacks, tape file formats.');
INSERT INTO source (id, title, author, publisher, year, kind, url, notes) VALUES (100008, 'Model PC-4 Pocket Computer Programming Guide', NULL, 'Tandy / Radio Shack', NULL, 'MANUAL', 'https://archive.org/details/Model_PC-4_Pocket_Computer_Programming_Guide_19xx_Tandy', 'Tutorial for the TRS-80 PC-4 (the same BASIC). Uses character arrays: K$(0) to K$(9) are the memories K to T.');
INSERT INTO source (id, title, author, publisher, year, kind, url, notes) VALUES (100009, 'PokecomGO2 (pokecom2)', 'digihori (Horiuchi)', NULL, NULL, 'WEB', 'https://github.com/digihori/pokecom2', 'Android PB-100 simulator: the BASIC is rewritten in Java (SBasic.java), the ROM is not used. Its results show what its author implemented, not what the machine does: the FOR stack has no limit, NEXT without FOR and RETURN without GOSUB give error 2, commands it does not run in a program (LIST, DEFM, VER, LOAD, SAVE, RUN) are skipped, CLEAR in a program works like VAC, READ/DATA/RESTORE/ON/BEEP/LET are added.');
INSERT INTO data_type (id, layer_id, code, name, suffix, type_class_id, minimum, maximum, bytes, notes) VALUES (100001, 2, 'REAL', 'Real number', NULL, 3, -9.999999999e+99, 9.999999999e+99, NULL, 'Absolute values from 1E-99 to 9.999999999E99, and 0; calculations use 12 mantissa digits, the display shows 10 (8 with an exponent). Below 1E-99 the result becomes 0; above the range: error 3. A memory takes the place of 8 program steps. In a program a number is stored as its characters; the exponent is a character of its own: ᴇ (code $1F), or ᴇ- ($1E) for a negative exponent (source [5]).');
INSERT INTO data_type (id, layer_id, code, name, suffix, type_class_id, minimum, maximum, bytes, notes) VALUES (100002, 2, 'STRING', 'Character string', '$', 4, NULL, NULL, NULL, 'Up to 7 characters in a character variable (A$-Z$), up to 30 in the exclusive character variable $. Only joining (+) and comparison are possible.');
INSERT INTO variable_kind (id, layer_id, code, name, data_type_id, dimensions, name_rule, name_pattern, max_name_length, significant_chars, examples, notes) VALUES (100001, 2, 'NUMERIC', 'Numeric variable', 100001, 0, 'one letter', '^[A-Z]$', 1, 0, 'A, Z', 'The 26 memories A-Z. A memory holds either a number or a string: the same letter cannot be used as numeric and character variable at the same time (error 6).');
INSERT INTO variable_kind (id, layer_id, code, name, data_type_id, dimensions, name_rule, name_pattern, max_name_length, significant_chars, examples, notes) VALUES (100002, 2, 'STRING', 'Character variable', 100002, 0, 'one letter followed by $', '^[A-Z]\$$', 1, 0, 'A$, X$', 'Up to 7 characters. Uses the memory of the numeric variable with the same letter.');
INSERT INTO variable_kind (id, layer_id, code, name, data_type_id, dimensions, name_rule, name_pattern, max_name_length, significant_chars, examples, notes) VALUES (100003, 2, 'EXCLUSIVE_STRING', 'Exclusive character variable', 100002, 0, 'the sign $ alone', '^\$$', NULL, NULL, '$', 'Up to 30 characters, in a special memory not counted by DEFM. MID works on it only.');
INSERT INTO variable_kind (id, layer_id, code, name, data_type_id, dimensions, name_rule, name_pattern, max_name_length, significant_chars, examples, notes) VALUES (100004, 2, 'NUMERIC_ARRAY', 'Numeric array', 100001, 1, 'one letter followed by a subscript in parentheses', '^[A-Z]$', 1, 0, 'A(5), Z(10)', 'There is no DIM: an array is a view of the memories. A(0) = A, A(1) = B, ..., A(25) = Z; in general the element X(i) is the memory i places after X, so B(24) = Z and Z(1) is the first expanded memory (A(221) = Z(196) with all 222 memories). Expand the memories with DEFM before using elements beyond Z.');
INSERT INTO variable_kind (id, layer_id, code, name, data_type_id, dimensions, name_rule, name_pattern, max_name_length, significant_chars, examples, notes) VALUES (100005, 2, 'STRING_ARRAY', 'Character array', 100002, 1, 'one letter followed by $ and a subscript in parentheses', '^[A-Z]\$$', 1, 0, 'A$(5), K$(9)', 'Like the numeric array, a view of the memories: A$(0) = A$, A$(1) = B$, ...; an element uses the memory of the numeric element with the same letter and subscript, and holds up to 7 characters. Source [8] (PC-4 guide): `K$(0)` to `K$(9)` are the memories K to T, so they cannot be used together with K(0)-K(9). The FX-700P manual shows numeric arrays only: not tested.');
INSERT INTO variable_layout_field (variable_kind_id, position, name, offset, size, description, evidence) VALUES (100001, 1, 'Exponent', 0, 1, 'Nibbles 0-1: the last two digits of the exponent plus 100, units first (exponent 2 → 102 → nibbles 2, 0).', 'MANUAL');
INSERT INTO variable_layout_field (variable_kind_id, position, name, offset, size, description, evidence) VALUES (100001, 2, 'Sign and first exponent digit', NULL, NULL, 'Nibble 2: the first digit of the exponent plus 100, plus 5 if the mantissa is negative: 0 = positive mantissa and negative exponent, 1 = positive and positive, 5 = negative and negative, 6 = negative and positive.', 'MANUAL');
INSERT INTO variable_layout_field (variable_kind_id, position, name, offset, size, description, evidence) VALUES (100001, 3, 'Mantissa', NULL, NULL, 'Nibbles 3-14: the 12 digits of the mantissa (1.00000000000 to 9.99999999999), last digit first.', 'MANUAL');
INSERT INTO variable_layout_field (variable_kind_id, position, name, offset, size, description, evidence) VALUES (100001, 4, 'Type', NULL, NULL, 'Nibble 15: 0 for a number. Zero is stored as 8 bytes $00 (also the empty string).', 'MANUAL');
INSERT INTO variable_layout_field (variable_kind_id, position, name, offset, size, description, evidence) VALUES (100004, 1, 'Exponent', 0, 1, 'Nibbles 0-1: the last two digits of the exponent plus 100, units first (exponent 2 → 102 → nibbles 2, 0).', 'MANUAL');
INSERT INTO variable_layout_field (variable_kind_id, position, name, offset, size, description, evidence) VALUES (100004, 2, 'Sign and first exponent digit', NULL, NULL, 'Nibble 2: the first digit of the exponent plus 100, plus 5 if the mantissa is negative: 0 = positive mantissa and negative exponent, 1 = positive and positive, 5 = negative and negative, 6 = negative and positive.', 'MANUAL');
INSERT INTO variable_layout_field (variable_kind_id, position, name, offset, size, description, evidence) VALUES (100004, 3, 'Mantissa', NULL, NULL, 'Nibbles 3-14: the 12 digits of the mantissa (1.00000000000 to 9.99999999999), last digit first.', 'MANUAL');
INSERT INTO variable_layout_field (variable_kind_id, position, name, offset, size, description, evidence) VALUES (100004, 4, 'Type', NULL, NULL, 'Nibble 15: 0 for a number. Zero is stored as 8 bytes $00 (also the empty string).', 'MANUAL');
INSERT INTO variable_layout_field (variable_kind_id, position, name, offset, size, description, evidence) VALUES (100002, 1, 'Characters', 0, 7, 'Nibbles 0-13: up to 7 character codes, each low nibble first; unused places $00.', 'MANUAL');
INSERT INTO variable_layout_field (variable_kind_id, position, name, offset, size, description, evidence) VALUES (100002, 2, 'Separator', NULL, NULL, 'Nibble 14: 0.', 'MANUAL');
INSERT INTO variable_layout_field (variable_kind_id, position, name, offset, size, description, evidence) VALUES (100002, 3, 'Length', NULL, NULL, 'Nibble 15: number of characters, 1-7. Not being 0, it tells a string from a number.', 'MANUAL');
INSERT INTO variable_layout_field (variable_kind_id, position, name, offset, size, description, evidence) VALUES (100005, 1, 'Characters', 0, 7, 'Nibbles 0-13: up to 7 character codes, each low nibble first; unused places $00.', 'MANUAL');
INSERT INTO variable_layout_field (variable_kind_id, position, name, offset, size, description, evidence) VALUES (100005, 2, 'Separator', NULL, NULL, 'Nibble 14: 0.', 'MANUAL');
INSERT INTO variable_layout_field (variable_kind_id, position, name, offset, size, description, evidence) VALUES (100005, 3, 'Length', NULL, NULL, 'Nibble 15: number of characters, 1-7. Not being 0, it tells a string from a number.', 'MANUAL');
INSERT INTO variable_layout_field (variable_kind_id, position, name, offset, size, description, evidence) VALUES (100003, 1, 'Length', 0, 1, 'Number of characters, 0-30.', 'MANUAL');
INSERT INTO variable_layout_field (variable_kind_id, position, name, offset, size, description, evidence) VALUES (100003, 2, 'Characters', 1, NULL, 'The character codes.', 'MANUAL');
INSERT INTO variable_layout_field (variable_kind_id, position, name, offset, size, description, evidence) VALUES (100003, 3, 'End', NULL, 1, '$FF.', 'MANUAL');
INSERT INTO parameter_kind (id, layer_id, code, name, nature, type_class_id, variable_kind_id, notes) VALUES (100001, 2, 'NUM_LITERAL', 'Numeric literal', 'LITERAL', 1, NULL, NULL);
INSERT INTO parameter_kind (id, layer_id, code, name, nature, type_class_id, variable_kind_id, notes) VALUES (100002, 2, 'STR_LITERAL', 'String literal', 'LITERAL', 4, NULL, 'Enclosed in quotes.');
INSERT INTO parameter_kind (id, layer_id, code, name, nature, type_class_id, variable_kind_id, notes) VALUES (100003, 2, 'NUM_EXPR', 'Numeric expression', 'EXPRESSION', 1, NULL, NULL);
INSERT INTO parameter_kind (id, layer_id, code, name, nature, type_class_id, variable_kind_id, notes) VALUES (100004, 2, 'STR_EXPR', 'Character expression', 'EXPRESSION', 4, NULL, 'String literal, character variable, character array element, $, MID or KEY, or a sum of them.');
INSERT INTO parameter_kind (id, layer_id, code, name, nature, type_class_id, variable_kind_id, notes) VALUES (100005, 2, 'NUM_VAR', 'Numeric variable', 'VARIABLE', NULL, 100001, NULL);
INSERT INTO parameter_kind (id, layer_id, code, name, nature, type_class_id, variable_kind_id, notes) VALUES (100006, 2, 'STR_VAR', 'Character variable', 'VARIABLE', NULL, 100002, 'A$-Z$ or the exclusive $.');
INSERT INTO parameter_kind (id, layer_id, code, name, nature, type_class_id, variable_kind_id, notes) VALUES (100007, 2, 'ARRAY_ELEMENT', 'Array element', 'ARRAY_ELEMENT', NULL, 100004, 'E.g. A(5).');
INSERT INTO parameter_kind (id, layer_id, code, name, nature, type_class_id, variable_kind_id, notes) VALUES (100011, 2, 'STR_ARRAY_ELEMENT', 'Character array element', 'ARRAY_ELEMENT', NULL, 100005, 'E.g. K$(3). Source [8]; not tested on the FX-700P.');
INSERT INTO parameter_kind (id, layer_id, code, name, nature, type_class_id, variable_kind_id, notes) VALUES (100008, 2, 'ANY_VAR', 'Any variable', 'VARIABLE', NULL, NULL, 'Numeric or character variable, $ or array element (numeric or character).');
INSERT INTO parameter_kind (id, layer_id, code, name, nature, type_class_id, variable_kind_id, notes) VALUES (100009, 2, 'CONDITION', 'Comparison', 'CONDITION', 1, NULL, 'Two numeric expressions, or two character expressions, joined by = ≠ > ≥ < ≤. Strings are compared by their character codes; numbers and strings cannot be compared.');
INSERT INTO parameter_kind (id, layer_id, code, name, nature, type_class_id, variable_kind_id, notes) VALUES (100010, 2, 'STATEMENT', 'Statement', 'STATEMENT', NULL, NULL, NULL);
INSERT INTO feature (layer_id, feature_kind_id, value, verified, notes) SELECT 2, id, '1-9999', 0, 'A line with the same number as an existing one replaces it.' FROM feature_kind WHERE code = 'LINE_NUMBERS';
INSERT INTO feature (layer_id, feature_kind_id, value, verified, notes) SELECT 2, id, 'Yes', 0, 'A line holds up to 62 characters, line number included. VAC and EXP cannot be used in a multistatement.' FROM feature_kind WHERE code = 'MULTIPLE_STATEMENTS';
INSERT INTO feature (layer_id, feature_kind_id, value, verified, notes) SELECT 2, id, ':', 0, NULL FROM feature_kind WHERE code = 'STATEMENT_SEPARATOR';
INSERT INTO feature (layer_id, feature_kind_id, value, verified, notes) SELECT 2, id, 'Absent', 0, 'There is no LET keyword: an assignment is written `variable = expression`.' FROM feature_kind WHERE code = 'LET';
INSERT INTO feature (layer_id, feature_kind_id, value, verified, notes) SELECT 2, id, 'None', 0, 'Comparisons can only be written in IF: they produce no value.' FROM feature_kind WHERE code = 'TRUE_VALUE';
INSERT INTO feature (layer_id, feature_kind_id, value, verified, notes) SELECT 2, id, 'None', 0, 'Comparisons can only be written in IF: they produce no value.' FROM feature_kind WHERE code = 'FALSE_VALUE';
INSERT INTO feature (layer_id, feature_kind_id, value, verified, notes) SELECT 2, id, 'Comparison only', 0, 'IF needs a comparison; a number alone is not a condition.' FROM feature_kind WHERE code = 'TRUTH_TEST';
INSERT INTO feature (layer_id, feature_kind_id, value, verified, notes) SELECT 2, id, 'Truncation (the decimal part is cut off)', 0, 'Stated for the line and area numbers of GOTO and GOSUB, the position of CSR and the arguments of MID.' FROM feature_kind WHERE code = 'INTEGER_CONVERSION';
INSERT INTO feature (layer_id, feature_kind_id, value, verified, notes) SELECT 2, id, 'Both', 0, 'With S the alphabet keys give statements (one-key commands), with F functions; everything can also be typed letter by letter.' FROM feature_kind WHERE code = 'MODAL_KEYBOARD';
INSERT INTO feature (layer_id, feature_kind_id, value, verified, notes) SELECT 2, id, 'None', 0, 'No zones: after '','' the next item is shown on a cleared display, after '';'' it follows the previous one.' FROM feature_kind WHERE code = 'TAB_ZONE_WIDTH';
INSERT INTO feature (layer_id, feature_kind_id, value, verified, notes) SELECT 2, id, 'Yes', 0, 'CSR n (0-11) inside PRINT shows the next item from position n.' FROM feature_kind WHERE code = 'VARIABLE_TAB_STOPS';
INSERT INTO feature (layer_id, feature_kind_id, value, verified, notes) SELECT 2, id, 'Yes', 0, 'From the PokecomGO2 simulator (source [9]): `FOR I=5 TO 1` executes the body once. Weak evidence: in its code the test that should skip the loop always succeeds, so it never skips. Not tested on the real machine.' FROM feature_kind WHERE code = 'FOR_RUNS_ONCE';
INSERT INTO feature (layer_id, feature_kind_id, value, verified, notes) SELECT 2, id, 'Yes', 0, 'From the PokecomGO2 simulator (source [9]): `I=I+4` inside `FOR I=1 TO 10` gives 5, then 10, then the loop ends. Not tested on the real machine.' FROM feature_kind WHERE code = 'FOR_VARIABLE_CHANGEABLE';
INSERT INTO error (layer_id, code, number, message, description) VALUES (2, 'MEMORY_OVERFLOW', 1, 'ERR1', 'Memory overflow or system stack overflow: not enough program steps, or a formula too complex for the stack.');
INSERT INTO error (layer_id, code, number, message, description) VALUES (2, 'SYNTAX', 2, 'ERR2', 'Syntax error: format error in the program, different formats on the two sides of an assignment, etc.');
INSERT INTO error (layer_id, code, number, message, description) VALUES (2, 'MATHEMATICAL', 3, 'ERR3', 'Mathematical error: a result of 1E100 or more, an argument outside the range of a function, or a result that is indefinite or impossible.');
INSERT INTO error (layer_id, code, number, message, description) VALUES (2, 'UNDEFINED_LINE', 4, 'ERR4', 'Undefined line number: the line of a GOTO or GOSUB does not exist.');
INSERT INTO error (layer_id, code, number, message, description) VALUES (2, 'ARGUMENT', 5, 'ERR5', 'Argument error: the argument of a command or function is outside its range.');
INSERT INTO error (layer_id, code, number, message, description) VALUES (2, 'VARIABLE', 6, 'ERR6', 'Variable error: a memory that has not been expanded, or the same memory used as a numeric and as a character variable at the same time.');
INSERT INTO error (layer_id, code, number, message, description) VALUES (2, 'NESTING', 7, 'ERR7', 'Nesting error: RETURN without GOSUB, NEXT outside a FOR loop, more than 8 subroutine levels or more than 4 FOR loops.');
INSERT INTO error (layer_id, code, number, message, description) VALUES (2, 'OPTION', 9, 'ERR9', 'Option error: no printer or tape recorder connected when PRT mode or a tape command such as SAVE is used.');
INSERT INTO error_rule (layer_id, selector, selector_value, error_code, cause, verified) VALUES (2, 'PARAMETER_KIND', 'NUM_EXPR', 'MATHEMATICAL', 'A calculation in the expression goes out of range, or its result is indefinite or impossible.', 0);
INSERT INTO error_rule (layer_id, selector, selector_value, error_code, cause, verified) VALUES (2, 'PARAMETER_KIND', 'NUM_EXPR', 'VARIABLE', 'The expression uses a memory that has not been expanded, or a numeric and a character variable of the same letter.', 0);
