INSERT INTO entry (id, layer_id, name, category_id, description, notes) VALUES (100047, 2, '-', 4, 'Change of sign and subtraction.', 'The manual does not say where the change of sign stands in the order of calculation. It is placed **before** the power as in the PokecomGO2 simulator (source [9]), where `-2↑2` gives 4, that is `(-2)↑2`, not -4; there it can also follow another operator (`2↑-2` = 0.25, `3--2` = 5, `-2*-3` = 6) or a function (`SIN -30` = -0.5 in MODE 4). Not tested on the real machine.');
