INSERT INTO open_question (layer_id, position, question) VALUES (2, 1, 'Character codes $3A-$3F, $5A, $5B, $7A-$7F have a blank glyph: are they used? bas2fx70 maps @ to $65 (× in the image, @ is $64) and \ to $7A (blank): which is right?');
