INSERT INTO open_question (layer_id, position, question) VALUES (2, 4, 'Commands in a program (LIST, CLEAR, DEFM, VER, RUN, LOAD, SAVE): what does the real machine do? The PokecomGO2 simulator skips them (CLEAR works like VAC) and is no evidence.');
INSERT INTO open_question (layer_id, position, question) VALUES (2, 5, 'FOR: body executed at least once? loop variable changeable inside? at most 4 nested loops (manual, source [7])? Error of NEXT without FOR and RETURN without GOSUB (7 in the manual, 2 in PokecomGO2)?');
